-- A256 complemento: leitura de observação interna da Quadra; não cria preço, disponibilidade, venda, contrato ou financeiro.
create or replace function public.subdivision_list_draft_physical_structure_v4(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_development_id uuid) returns table(block_id uuid,block_number integer,sector_reference text,block_typology public.subdivision_block_typology,internal_note text,lots jsonb) language plpgsql security definer set search_path='' as $$ begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); if not exists(select 1 from public.subdivision_developments d where d.id=p_development_id and d.organization_id=p_organization_id and d.state='draft'::public.party_lifecycle_state) then raise exception using errcode='42501',message='SUBDIVISION_DEVELOPMENT_CONTEXT_DENIED'; end if; return query select block.id,block.block_number,block.sector_reference,block.block_typology,note.internal_note,coalesce(jsonb_agg(jsonb_build_object('lot_number',lot.lot_number,'area_sqm',lot.area_sqm,'frontage_m',lot.frontage_m,'depth_m',lot.depth_m,'lot_typology',lot.lot_typology::text,'position_code',lot.position_code::text,'reservation_purpose',reservation.reservation_purpose::text,'internal_note',lot_note.internal_note) order by lot.lot_number) filter(where lot.id is not null),'[]'::jsonb) from public.subdivision_blocks block left join public.subdivision_lots lot on lot.block_id=block.id and lot.organization_id=p_organization_id and lot.state='draft'::public.party_lifecycle_state left join public.subdivision_lot_physical_reservations reservation on reservation.lot_id=lot.id and reservation.organization_id=lot.organization_id left join public.subdivision_lot_internal_notes lot_note on lot_note.lot_id=lot.id and lot_note.organization_id=lot.organization_id left join public.subdivision_block_internal_notes note on note.block_id=block.id and note.organization_id=block.organization_id where block.organization_id=p_organization_id and block.development_id=p_development_id and block.state='draft'::public.party_lifecycle_state group by block.id,block.block_number,block.sector_reference,block.block_typology,note.internal_note order by block.block_number,block.id; end; $$;
revoke all on function public.subdivision_list_draft_physical_structure_v4(uuid,uuid,public.operating_module,text,uuid) from public,anon,authenticated;
grant execute on function public.subdivision_list_draft_physical_structure_v4(uuid,uuid,public.operating_module,text,uuid) to service_role;
